import * as React from "react";

export type MinusCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MinusCircleIcon({ size = 20, ...props }: MinusCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5"/><path d="M8.5 12h7"/>
    </svg>
  );
}
